// index.js
import React from 'react';
import ReactDOM from 'react-dom';
import { MultiSelect } from 'carbon-components-react';
import 'carbon-components/css/carbon-components.min.css';

const items = [
  {
    id: 'item-1',
    text: 'An example option that is really long to show what should be done to handle long text',
  },
  { id: 'item-2', text: 'Option 1' },
  { id: 'item-3', text: 'Option 2' },
  { id: 'item-4', text: 'Option 3' },
  { id: 'item-5', text: 'Option 4' },
];

const initialSelectedItems = [items[1], items[2]];

function App() {
  return (
    <div style={{ padding: '2rem', maxWidth: '300px' }}>
      <MultiSelect
        id="carbon-multiselect-example"
        titleText="Multiselect title"
        helperText="This is not helper text"
        label="MultiSelect Label"
        items={items}
        initialSelectedItems={initialSelectedItems}
        itemToString={item => (item ? item.text : '')}
        translateWithId={(id) => {
          // use default translations
          const translations = {
            'clear.all': 'Clear all',
            'clear.selection': 'Clear',
            'open.menu': 'Open menu',
            'close.menu': 'Close menu',
          };
          return translations[id];
        }}
      />
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
